insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('110ded91-0622-4b60-b9dd-5c353fa57fb1', 'd71b621f-4f26-4158-b89d-d3cb16e0bc3a', $$inleiding: kunstmatig rif in het Grevelingenmeer$$,
   $$biologie-havo-2018-i-rifbollen-context1.png$$,
   $$Om de afname van het aantal diersoorten in het Grevelingenmeer te stoppen werd er 15 jaar geleden een kunstmatig rif aangelegd. Al na een paar jaar werd het rif een populaire plek voor duikers.$$, 'inline'),
  ('ad3481c5-1098-4444-ba23-d4cff5b78592', 'd71b621f-4f26-4158-b89d-d3cb16e0bc3a', $$kaart Grevelingenmeer (afbeelding 1) en betonnen rifbollen als stenige leefplek (afbeelding 2)$$,
   $$biologie-havo-2018-i-rifbollen-context2.png$$,
   $$afbeelding 1: kaart van de Noordzee, de Brouwersdam, het Grevelingenmeer en de Oosterschelde (legenda: zout water, zoet water)
afbeelding 2: foto van betonnen rifbollen
Na de bouw van de Brouwersdam verdween de getijdenstroom in het Grevelingenmeer (afbeelding 1) waardoor steeds meer van de stenige bodem bedekt raakte met zand en slib. Juist op stenige plekken kunnen holtedieren, sponzen en planten (zoals wieren) groeien, waartussen vissen, kreeften, krabben en andere dieren beschutting en voedsel zoeken. Het kunstmatig rif van betonnen rifbollen (afbeelding 2) biedt deze organismen weer een plaats om te leven.$$, 'inline'),
  ('4962320e-863e-4617-80e1-0e8a9777a7c0', 'd71b621f-4f26-4158-b89d-d3cb16e0bc3a', $$rifbollen worden geplaatst op 5 tot 9 meter diepte$$,
   $$biologie-havo-2018-i-rifbollen-context3.png$$,
   $$Rifbollen worden geplaatst op plekken waar het water 5 tot 9 meter diep is.$$, 'inline'),
  ('50d510be-e30e-4d27-a9fd-c322541c2c0e', 'd71b621f-4f26-4158-b89d-d3cb16e0bc3a', $$helder, voedselarm water met weinig nitraat; algen laag gehouden door filteraars$$,
   $$biologie-havo-2018-i-rifbollen-context4.png$$,
   $$Dat het water bijna altijd helder is, draagt zeker bij aan de populariteit van het Grevelingenmeer in de duiksport. De algenbloei die in mei het water van de Oosterschelde meestal in een troebele groene soep verandert, komt hier niet voor. Er stroomt geen rivierwater naar het Grevelingenmeer, waardoor het water voedselarm blijft: het water bevat relatief weinig nitraat. Hierdoor kunnen kokkels, mosselen en dierlijk plankton de populatiedichtheid van de algen laag houden.$$, 'inline'),
  ('894a59a0-ab11-49c4-b485-ca3399f3544f', 'd71b621f-4f26-4158-b89d-d3cb16e0bc3a', $$experiment: groeisnelheid van algen bij verschillende nitraatconcentraties$$,
   $$biologie-havo-2018-i-rifbollen-context5.png$$,
   $$In een laboratorium wordt een experiment uitgevoerd waarbij de groeisnelheid van algenpopulaties wordt bepaald bij verschillende nitraatconcentraties. De algen zijn afkomstig uit het water van het Grevelingenmeer. In afbeelding 3 is het resultaat van dit onderzoek weergegeven.$$, 'inline'),
  ('a40e01eb-c7b8-47d8-81ff-51f2092f994b', 'd71b621f-4f26-4158-b89d-d3cb16e0bc3a', $$afbeelding 3: optimumkromme groeisnelheid algen tegen nitraatconcentratie (punten P-T)$$,
   $$biologie-havo-2018-i-rifbollen-context6.png$$,
   $$afbeelding 3: optimumkromme van de groeisnelheid (verticale as) tegen de nitraatconcentratie (horizontale as); onder de kromme staan van links naar rechts de punten P, Q, R, S en T.$$, 'inline'),
  ('73fb4264-f5c6-4be0-9d75-e83bf9b6cf1e', 'd71b621f-4f26-4158-b89d-d3cb16e0bc3a', $$vijf punten met een letter onder de optimumkromme$$,
   $$biologie-havo-2018-i-rifbollen-context7.png$$,
   $$Onder de optimumkromme zijn vijf punten met een letter aangegeven.$$, 'inline'),
  ('861f792c-f228-4620-af9c-dc887564ed9d', 'd71b621f-4f26-4158-b89d-d3cb16e0bc3a', $$aanvoer van organische stoffen via rivieren veroorzaakt algenbloei$$,
   $$biologie-havo-2018-i-rifbollen-context8.png$$,
   $$Aanvoer van organische stoffen via rivieren veroorzaakt algenbloei in de Oosterschelde.$$, 'inline'),
  ('dfc29b59-0c7e-45c5-9c4e-f04ee26557e7', 'd71b621f-4f26-4158-b89d-d3cb16e0bc3a', $$tabel 1 diersoorten op de rifbollen met voedsel, en piramide van biomassa (afbeelding 4)$$,
   $$biologie-havo-2018-i-rifbollen-context9.png$$,
   $$In een aantal jaren zijn de kale betonnen rifbollen veranderd in een klein ecosysteem. Een deel van de diersoorten die hier worden aangetroffen staat in tabel 1.
tabel 1 (diersoort – afdeling – voedsel)
zeeanjelier – holtedieren – dierlijk plankton, visjes en krabbetjes
grote zeenaald – gewervelden – kreeftjes en garnalen
zeekreeft – geleedpotigen – schelpdieren, garnaaltjes, dierlijk aas
geweispons – sponzen – algen en organisch afval
mossel – weekdieren – algen
gewone zeester – stekelhuidigen – mosselen
doorschijnende zakpijp – manteldieren – algen en dierlijk plankton
De organismen in een ecosysteem kunnen worden gerangschikt in een piramide van biomassa (afbeelding 4). Hierin is de hoeveelheid biomassa van de verschillende trofische niveaus weergegeven.
afbeelding 4: piramide met van onder naar boven de lagen P, C1, C2, C3, C4 en C5.$$, 'inline'),
  ('ce0146bc-8014-4d46-8981-6e0678e7a02a', 'd71b621f-4f26-4158-b89d-d3cb16e0bc3a', $$twee uitspraken over de gevolgen van de introductie van de rifbollen$$,
   $$biologie-havo-2018-i-rifbollen-context10.png$$,
   $$De introductie van de rifbollen veranderde het ecosysteem in het Grevelingenmeer. Hierover worden twee uitspraken gedaan:
1 De introductie van de rifbollen heeft tot een toename van producenten geleid.
2 De introductie van de rifbollen heeft ertoe geleid dat de habitat voor holtedieren groter werd.$$, 'inline'),
  ('f14a6a9d-03b1-41fa-8f76-f53a80ca85c0', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$inleiding: ontdekking over longinfecties bij taaislijmziekte$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context1.png$$,
   $$Wetenschappers hebben mogelijk ontdekt waardoor de longen van patiënten met taaislijmziekte snel geïnfecteerd raken. Deze ontdekking zou kunnen leiden tot een behandelmethode om longinfecties bij deze patiënten te voorkomen.$$, 'inline'),
  ('c6368987-2d39-4ac7-b343-f6dc95a6a3ee', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$CF: afwijking in het CFTR-gen, zuurdere slijmlaag, bacteriën niet gedood door lysozymen$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context2.png$$,
   $$Patiënten met taaislijmziekte (cystische fibrose, CF) hebben een afwijking in het CFTR-gen waardoor de slijmvliezen in het lichaam dik, taai slijm produceren. Het was tot nu toe onduidelijk hoe dit in de longen leidt tot een verstoorde afweer, bijvoorbeeld tegen bacteriën. Nu blijkt dat bij patiënten met CF de dunne slijmlaag van het longslijmvlies zuurder is dan bij gezonde personen. Hierdoor worden ingeademde bacteriën niet gedood door lysozymen. Dit probleem kan mogelijk in een vroeg stadium worden aangepakt door de slijmlaag minder zuur te maken.$$, 'inline'),
  ('3bdfdf48-bcc0-43d7-9476-6fee3b1a9957', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$vier manieren waarop bacteriën onschadelijk gemaakt worden$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context3.png$$,
   $$Bacteriën kunnen op verschillende manieren onschadelijk gemaakt worden:
1 Macrofagen verteren de bacteriën in de longblaasjes.
2 Trilharen verplaatsen de bacteriën naar de keelholte. Na het doorslikken worden ze door het maagzuur gedood.
3 T-lymfocyten en B-lymfocyten maken de bacteriën onschadelijk.
4 Lysozymen breken de celwand van bacteriën af.$$, 'inline'),
  ('7a6df216-a13d-4a9a-9e81-349de0941831', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$hypothese van Haagsman en experiment met longslijmvlies van varkens (NaCl, CO₂, NaHCO₃)$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context4.png$$,
   $$Henk Haagsman, hoogleraar moleculaire afweer aan de Universiteit Utrecht, vermoedde een verband tussen de zuurdere slijmlaag en het veel voorkomen van longinfecties bij CF. Zijn hypothese was: de werking van bacteriedodende eiwitten (lysozymen) in het longslijmvlies wordt bij patiënten met CF geremd door de lagere pH. Om deze hypothese te testen werd een experiment uitgevoerd met varkens. Het longslijmvlies van gezonde varkens werd behandeld met een NaCl-oplossing of met CO₂. Door de CO₂ wordt de pH van het longslijmvlies verlaagd, waardoor deze overeenkomt met de pH van het longslijmvlies van varkens met CF. Met NaCl blijft de pH hetzelfde. Het longslijmvlies van varkens met CF werd behandeld met NaCl of met NaHCO₃. Door NaHCO₃ wordt de pH verhoogd, zodat de pH van gezonde varkenslongen benaderd wordt. Vervolgens werd bij de vier groepen varkens het longslijmvlies geïnfecteerd met de bacterie Staphylococcus aureus. Hierna werd de sterfte van deze bacteriën bepaald.$$, 'inline'),
  ('4b471418-6527-440d-beb6-baf05f3be995', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$biggen met en zonder CF; CF autosomaal recessief, biggen homozygoot$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context5.png$$,
   $$Voor het onderzoek heeft men nauw verwante biggen met en zonder CF vergeleken. CF wordt ook bij varkens veroorzaakt door een autosomaal recessief allel van het CFTR-gen. De biggen die in het onderzoek werden gebruikt waren allemaal homozygoot voor het CFTR-gen.$$, 'inline'),
  ('b7c1ff8f-45d1-44ef-aebf-97219cadb3c2', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$Haagsman vindt zijn hypothese aannemelijk$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context6.png$$,
   $$Haagsman concludeerde uit de resultaten van het onderzoek dat zijn hypothese aannemelijk is.$$, 'inline'),
  ('42388044-ae0f-4513-a74a-ca6df182ce50', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$afbeelding 1: vier diagrammen (P-S) met sterfte van Staphylococcus aureus in vier groepen$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context7.png$$,
   $$afbeelding 1: vier staafdiagrammen P, Q, R en S met de sterfte van Staphylococcus aureus (%) bij de groepen 1 tot en met 4.
P: groepen 1 en 2 hoog, groepen 3 en 4 laag
Q: groepen 2 en 3 hoog, groepen 1 en 4 laag
R: groepen 1 en 4 hoog, groepen 2 en 3 laag
S: groepen 3 en 4 hoog, groepen 1 en 2 laag
Legenda:
1: longslijmvlies van gezonde varkens behandeld met NaCl
2: longslijmvlies van gezonde varkens behandeld met CO₂
3: longslijmvlies van varkens met CF behandeld met NaCl
4: longslijmvlies van varkens met CF behandeld met NaHCO₃$$, 'inline'),
  ('3d8deb79-6158-4e91-af59-ada2a4731bf4', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$middel moet ook op mensen getest worden$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context8.png$$,
   $$Varkens met CF ontwikkelen dezelfde ziekteverschijnselen als mensen met CF. Toch moet het middel ook op mensen worden getest voordat het toegepast kan worden als behandelmethode voor patiënten met CF.$$, 'inline'),
  ('9a49bdfd-adad-4960-a822-fbf543d5df74', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$NaHCO₃ inademen met een inhalator (afbeelding 2)$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context9.png$$,
   $$Onderzoek bij patiënten moet uitwijzen of het mogelijk is om de longen minder zuur te maken, zegt Haagsman. Dit kan bijvoorbeeld door met een inhalator (afbeelding 2) NaHCO₃ in te ademen zodat het in de longen komt.
afbeelding 2: foto van een vrouw die een inhalator gebruikt$$, 'inline'),
  ('96f5f10a-d299-4ee2-b67f-3d1fcefd9a36', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$hielprikonderzoek bij pasgeborenen op CF$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context10.png$$,
   $$Vroegtijdig behandelen van kinderen met CF is mogelijk, omdat de ziekte is opgenomen in het hielprikonderzoek voor pasgeborenen. Bij deze hielprik wordt bloed afgenomen dat onder andere wordt geanalyseerd om te bepalen of de baby wel of geen CF heeft.$$, 'inline'),
  ('5eb26514-1203-48bf-acba-9ba1c4a4a1df', '194dbe2f-f230-466f-91ea-ce9f0c8ccb59', $$toekomstige behandeling van longinfecties met NaHCO₃$$,
   $$biologie-havo-2018-i-longinfecties-bij-cf-patienten-context11.png$$,
   $$In de toekomst kunnen longinfecties bij CF-patiënten mogelijk worden voorkomen door behandeling met NaHCO₃.$$, 'inline'),
  ('e785021e-7088-4619-bc0e-ef8f0ed543ef', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$inleiding: hersenonderzoek met röntgen en fMRI$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context1.png$$,
   $$Vanaf halverwege de vorige eeuw kunnen kleine hersengebieden onderzocht worden door middel van röntgenonderzoek. Sinds 1990 kan met ‘functional Magnetic Resonance Imaging’ (fMRI) vrij precies de hersenactiviteit worden gemeten (afbeelding 1). De conclusies van sommige fMRI-studies staan echter ter discussie.$$, 'inline'),
  ('d204212e-64c9-440b-b840-11e79849d93a', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$afbeelding 1: foto van een MRI-scanner$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context2.png$$,
   $$afbeelding 1: foto van een fMRI-scanner met een patiënt en een onderzoeker$$, 'inline'),
  ('3fcaf6a5-efbf-4b8f-92d3-cd7f7f3b4dad', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$hersencentra gelokaliseerd bij patiënten met hersenbeschadiging$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context3.png$$,
   $$Bij het onderzoek naar welke gebieden in onze hersenen betrokken zijn bij het uitvoeren van bepaalde functies waren wetenschappers tot 1960 afhankelijk van patiënten die door een ongeluk een beschadiging in hun hersenen hadden opgelopen. Door gedragsobservaties bij deze patiënten konden de hersencentra voor geheugen, herkenning van personen en sociale aanpassing worden gelokaliseerd.$$, 'inline'),
  ('84be0e1c-634c-4fde-a498-b918288a99fb', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$fMRI meet doorbloeding met een resolutie van 2 millimeter (afbeelding 2)$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context4.png$$,
   $$Met fMRI wordt de doorbloeding van bepaalde hersengebieden bekeken (afbeelding 2), waarbij een resolutie van 2 millimeter kan worden bereikt. Dit betekent dat van een gebiedje van 2 bij 2 millimeter de verandering in hersendoorbloeding kan worden waargenomen. De doorbloeding van een hersengebied is een maat voor de hersenactiviteit van dat gebied.
afbeelding 2: foto van hersenscans$$, 'inline'),
  ('7f25e332-36ed-4e09-b473-3dc6af926fc8', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$drie uitspraken over de doorbloeding van actieve hersengebieden$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context5.png$$,
   $$Hieronder worden drie uitspraken gedaan over de doorbloeding in actieve hersengebieden:
1 Met het bloed worden meer blaasjes met neurotransmitters aangevoerd naar dit gebied.
2 Met het bloed wordt meer ATP aangevoerd naar dit gebied.
3 Met het bloed wordt meer zuurstof aangevoerd naar dit gebied.$$, 'inline'),
  ('2645ad7d-72d0-4193-9755-fd471a2bbe8b', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$fMRI-onderzoek naar het herkennen van klanken en sprekers$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context6.png$$,
   $$Met fMRI is het herkennen van klanken en het herkennen van degene die tot je spreekt, onderzocht. Proefpersonen kregen bij dat onderzoek verschillende klinkers (a, i of o) te horen van verschillende sprekers. De hersengebieden die actief zijn − onafhankelijk van welke klinker uitgesproken wordt − lijken betrokken bij het identificeren van de spreker.$$, 'inline'),
  ('a8d01994-c90b-4255-9428-eda1588cec22', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$onvolledige methodebeschrijving bij sommige fMRI-studies$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context7.png$$,
   $$Bij sommige fMRI-studies is de beschrijving van de gebruikte methode niet volledig, waardoor andere onderzoekers de getrokken conclusies niet kunnen controleren. Dit was bij het beschreven gehoor-/herkennings- onderzoek overigens wel mogelijk. Een voorbeeld van een slecht te controleren onderzoek is hieronder beschreven. De paragraaf Materiaal en methode bevat naast gedetailleerde technische methodieken de beschrijving in afbeelding 3.$$, 'inline'),
  ('020147b9-1f19-4450-b9cd-1b77f9088000', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$afbeelding 3: beschrijving van de proefpersonen in een slecht te controleren onderzoek$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context8.png$$,
   $$afbeelding 3
Bij een aantal gezonde proefpersonen, van uiteenlopende leeftijden, met evenveel mannen als vrouwen, werd tijdens het oplossen van een rekenprobleem een fMRI gemaakt.$$, 'inline'),
  ('c9abaaa4-41b7-48be-a553-5878abe5b7fc', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$resultaat: bij 75% van de proefpersonen verhoogde activiteit$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context9.png$$,
   $$In de resultaten werd vermeld dat bij 75% van de proefpersonen een verhoogde activiteit werd gemeten in een bepaald hersengebied, waaruit de conclusie werd getrokken dat dit hersengebied een rol speelde bij de onderzochte bezigheid.$$, 'inline'),
  ('ce3518b4-5595-49a2-8724-4376deb449ca', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$betrouwbaarheid en validiteit van onderzoek$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context10.png$$,
   $$De kwaliteit van dit onderzoek is niet vast te stellen, omdat de gegevens voor het bepalen van de betrouwbaarheid en de validiteit onvolledig zijn. Met een hoge betrouwbaarheid wordt bedoeld dat de invloed van toeval op de uitkomst beperkt is. Een onderzoek is valide wanneer geen systematische fouten worden gemaakt; dat wil dus zeggen dat gemeten wordt wat men wil weten.$$, 'inline'),
  ('1e4771fd-6562-419f-84ac-464b5cc123fb', 'bb2723df-11dd-4619-bf0b-0b99513f60e5', $$twee tekortkomingen in de onderzoeksbeschrijving$$,
   $$biologie-havo-2018-i-fmri-onderzoek-is-niet-altijd-te-reproduceren-context11.png$$,
   $$Twee tekortkomingen in de beschrijving van het onderzoek zijn:
1 Het aantal proefpersonen is niet vermeld.
2 De controleproef is niet beschreven.$$, 'inline'),
  ('2d1ab85d-7e66-4c49-9738-98c974034f31', 'bc15a159-284a-4905-a18b-7f9653b3ccf0', $$inleiding: onderzoek naar schimmelziekten in de bananenteelt$$,
   $$biologie-havo-2018-i-bananen-bedreigd-context1.png$$,
   $$Onder leiding van Gert Kema doet Plant Research International onderzoek naar schimmelziekten die een grote bedreiging vormen voor de bananenteelt.$$, 'inline'),
  ('87534368-fb3d-469c-9e3b-b970fcc56c9f', 'bc15a159-284a-4905-a18b-7f9653b3ccf0', $$bananenproductie en -export (afbeelding 1); eetbare rassen met drie sets chromosomen vermeerderen ongeslachtelijk$$,
   $$biologie-havo-2018-i-bananen-bedreigd-context2.png$$,
   $$De banaan is wereldwijd een belangrijk voedselgewas, met een productie van 100 miljoen ton per jaar. Ongeveer 15% van die bananen komt terecht in supermarkten in de VS en Europa (afbeelding 1).
afbeelding 1: wereldkaart met de grootste bananenproducenten (o.a. China, India, Brazilië, Kameroen, Tanzania, Filipijnen) en de grootste bananenexporteurs (Costa Rica, Panama, Columbia, Equador, Filipijnen), met pijlen naar de VS en Europa
Wilde bananen bevatten weinig vruchtvlees en veel harde zaden, en zijn daardoor oneetbaar. Uit de wilde bananensoorten Musa acuminata en Musa balbisiana zijn diverse eetbare rassen ontwikkeld. Veel van deze rassen hebben drie sets chromosomen, waardoor ze zich niet geslachtelijk voortplanten. Deze rassen worden ongeslachtelijk vermeerderd.$$, 'inline'),
  ('a620cd0b-b480-4bee-8aba-c0ca57c4b9fb', 'bc15a159-284a-4905-a18b-7f9653b3ccf0', $$plantages zijn monoculturen van dezelfde bananenkloon$$,
   $$biologie-havo-2018-i-bananen-bedreigd-context3.png$$,
   $$Elke plantage is een monocultuur van dezelfde bananenkloon. Hierdoor zijn de planten erg kwetsbaar als een schimmelziekte uitbreekt.$$, 'inline'),
  ('626e9a80-01bf-4e21-903a-bfcbd0e5181d', 'bc15a159-284a-4905-a18b-7f9653b3ccf0', $$Panamaziekte: bodemschimmel belemmert het vochttransport$$,
   $$biologie-havo-2018-i-bananen-bedreigd-context4.png$$,
   $$De Panamaziekte wordt veroorzaakt door een bodemschimmel die de plant via de wortels binnendringt. Daar belemmeren de schimmeldraden (mycelium) het vochttransport, waardoor de bladeren vergelen en de plant verwelkt.$$, 'inline'),
  ('15b76ac7-c262-427d-8c74-09fc4949ed2d', 'bc15a159-284a-4905-a18b-7f9653b3ccf0', $$Zwarte Sigatokaziekte via huidmondjes (afbeelding 2), bestreden met fungiciden$$,
   $$biologie-havo-2018-i-bananen-bedreigd-context5.png$$,
   $$Bij de schimmel Mycosphaerella fijiensis, die de Zwarte Sigatokaziekte veroorzaakt, verplaatsen de schimmelsporen zich via de lucht en besmetten de plant via de huidmondjes. Het gevolg is dat er vlekken op de bladeren ontstaan (afbeelding 2) en dat de vruchten van de plant versneld rijpen.
afbeelding 2: foto van een bananenblad met vlekken
De Zwarte Sigatokaziekte kan worden bestreden met fungiciden, bestrijdingsmiddelen tegen schimmels. Door grote bananenproducenten worden deze veelvuldig ingezet.$$, 'inline'),
  ('6010436d-1e9f-4289-b192-6a107f05cfd3', 'bc15a159-284a-4905-a18b-7f9653b3ccf0', $$stelling: bananenconsumptie in Europa en de VS is ecologisch niet duurzaam$$,
   $$biologie-havo-2018-i-bananen-bedreigd-context6.png$$,
   $$Het gebruik van fungiciden in de bananenteelt wordt in discussies gebruikt als argument voor de stelling: Consumptie van bananen in Europa en de VS is niet duurzaam vanuit ecologisch oogpunt.$$, 'inline'),
  ('89df0c29-0e00-44e1-b677-63072a5e024e', 'bc15a159-284a-4905-a18b-7f9653b3ccf0', $$schimmels worden resistent tegen het fungicide propiconazool$$,
   $$biologie-havo-2018-i-bananen-bedreigd-context7.png$$,
   $$Een fungicide zoals propiconazool doodt de schimmel, maar werkt vaak niet op de langere termijn. Dit komt doordat de schimmels resistent worden tegen het fungicide.$$, 'inline'),
  ('1659a1f2-bb8e-48d0-a45e-6f4048004c2b', 'bc15a159-284a-4905-a18b-7f9653b3ccf0', $$genetische modificatie met resistentiegenen uit wilde bananen$$,
   $$biologie-havo-2018-i-bananen-bedreigd-context8.png$$,
   $$Gert Kema heeft in verschillende landen onderzoeksprojecten opgezet die mogelijk leiden tot oplossingen voor de problemen in de bananenteelt. Een daarvan richt zich op het resistent maken van de bananenplant door genetische modificatie. Daarvoor willen de onderzoekers resistentiegenen uit wilde bananenrassen inbouwen in het DNA van gekweekte rassen.$$, 'inline'),
  ('5ac8574b-4b57-4560-ac40-8b8e927964b6', 'e9da4be2-ab24-4c29-a5c0-5c116e4efd66', $$inleiding: meeroken levert gezondheidseffecten op$$,
   $$biologie-havo-2018-i-meeroken-context1.png$$,
   $$Ondanks het rookverbod in openbare ruimten en de horeca zijn er nog veel plaatsen waar mensen min of meer gedwongen worden om mee te roken. Dit levert voor veel mensen nadelige gezondheidseffecten op.$$, 'inline'),
  ('cad630f4-3711-4600-a4a3-f7df588281d5', 'e9da4be2-ab24-4c29-a5c0-5c116e4efd66', $$astma: luchtwegen worden nauwer bij een aanval$$,
   $$biologie-havo-2018-i-meeroken-context2.png$$,
   $$Iemand met astma is extra gevoelig voor verblijf in rokerige ruimtes. Astma is een aandoening, waarbij de longen te heftig reageren op bepaalde prikkels, zoals sigarettenrook. Door deze prikkels kan een astma-aanval ontstaan. De luchtwegen worden tijdens zo’n aanval nauwer en dit leidt ertoe dat ademen moeilijker wordt. De patiënt krijgt het benauwd en kan gaan hoesten.$$, 'inline'),
  ('447e200d-732b-48c8-8402-c0bd5be0535b', 'e9da4be2-ab24-4c29-a5c0-5c116e4efd66', $$astmapatiënt ademt bij een aanval tot 80% minder lucht$$,
   $$biologie-havo-2018-i-meeroken-context3.png$$,
   $$Een astmapatiënt ademt bij een astma-aanval tot 80% minder lucht in en uit dan normaal.$$, 'inline'),
  ('e08d8e6a-5107-4ef0-9ef9-c348921643b4', 'e9da4be2-ab24-4c29-a5c0-5c116e4efd66', $$sigarettenrook bevat ongeveer 40 mutagene stoffen$$,
   $$biologie-havo-2018-i-meeroken-context4.png$$,
   $$Sigarettenrook bevat naast nicotine een paar duizend andere giftige stoffen, waarvan er ongeveer 40 mutageen zijn.$$, 'inline'),
  ('a8e1c4d7-9bbb-497b-a798-e1731f860927', 'e9da4be2-ab24-4c29-a5c0-5c116e4efd66', $$drie manieren waarop nicotine in het lichaam komt; snel verspreid via het bloed$$,
   $$biologie-havo-2018-i-meeroken-context5.png$$,
   $$Nicotine kan op verschillende manieren in het lichaam terechtkomen:
− via de huid door een nicotinepleister
− via de longen door (mee) te roken
− via de slijmvliezen van de neus door tabak te snuiven Als nicotine in het lichaam terechtkomt, wordt het snel verspreid door de bloedsomloop. Het duurt gemiddeld zeven seconden voordat de stof in de hersenen terechtkomt.$$, 'inline'),
  ('659fee3f-38f0-4a7c-9082-899b44831b00', 'e9da4be2-ab24-4c29-a5c0-5c116e4efd66', $$nicotine stimuleert het orthosympatisch zenuwstelsel en de bijnieren$$,
   $$biologie-havo-2018-i-meeroken-context6.png$$,
   $$Ook mensen met een hoge bloeddruk kunnen meeroken beter vermijden. In de hersenen veroorzaakt nicotine verschillende processen. Een daarvan is het stimuleren van het orthosympatisch zenuwstelsel, waardoor de bijnieren meer van een bepaald hormoon afgeven.$$, 'inline'),
  ('ad845ac9-ccc2-440c-82d6-0b74703927d2', 'e9da4be2-ab24-4c29-a5c0-5c116e4efd66', $$afbraak van nicotine tot cotinine; vier processen in de nieren$$,
   $$biologie-havo-2018-i-meeroken-context7.png$$,
   $$Nicotine verlaat het lichaam voor een deel direct via de nieren. Het grootste deel wordt echter afgebroken in de lever, waar nicotine wordt omgezet in cotinine. Deze stof wordt ook door de nieren uitgescheiden. In de nieren vinden verschillende processen plaats:
1 osmose
2 passief transport door de cellen van de nierkanaaltjes
3 reabsorptie (terugresorptie) door actief transport
4 ultrafiltratie in de kapsels van Bowman$$, 'inline'),
  ('7e7ca62e-2663-47a8-9de4-dd63050ab6ed', '8edfdb55-d98a-418e-877a-9455fca4008f', $$inleiding: veranderd voedingspatroon bij de domesticatie van de wolf$$,
   $$biologie-havo-2018-i-zetmeeldieet-maakte-van-de-wolf-een-hond-context1.png$$,
   $$Meer dan 10.000 jaar geleden is het voedingspatroon van de voorouders van onze huidige hond veranderd. Dit is een belangrijke stap geweest in de ontwikkeling van de wolf tot huisdier (domesticatie).
(foto van een hond tussen afval)$$, 'inline'),
  ('5220ca98-46e4-459b-8ad9-34ffb9aa2762', '8edfdb55-d98a-418e-877a-9455fca4008f', $$Axelsson: voorouder van de hond verteerde zetmeel beter; opkomst van de landbouw$$,
   $$biologie-havo-2018-i-zetmeeldieet-maakte-van-de-wolf-een-hond-context2.png$$,
   $$Volgens de Zweedse onderzoeker Axelsson is de domesticatie versneld doordat de voorouder van de huidige hond zetmeel beter kon verteren dan de wolf. De onderzoeker koppelt die aanpassing aan de opkomst van de landbouw, zo’n 11.000 jaar geleden. Mensen vestigden zich op vaste plaatsen waar ze granen en peulvruchten gingen verbouwen. Bij die nederzettingen was afval met voedselresten te vinden. Zo ontstond een nieuwe voedingsbron voor de wolf die mogelijk bijdroeg aan de ontwikkeling van de wolf tot hond.$$, 'inline'),
  ('ff7d5965-268d-4bb6-aaf1-16712382ce47', '8edfdb55-d98a-418e-877a-9455fca4008f', $$hond en wolf zijn in 11.000 jaar sterk van elkaar gaan verschillen$$,
   $$biologie-havo-2018-i-zetmeeldieet-maakte-van-de-wolf-een-hond-context3.png$$,
   $$In de loop van 11.000 jaar zijn hond en wolf sterk van elkaar gaan verschillen. Naast mutatie en selectie is er nog een factor die hierin een belangrijke rol heeft gespeeld.$$, 'inline'),
  ('c6d58013-65bc-45cc-8ad3-e4a1d61edab8', '8edfdb55-d98a-418e-877a-9455fca4008f', $$DNA-onderzoek bij wolven en honden; drie uitspraken over de onderzoeksgroep$$,
   $$biologie-havo-2018-i-zetmeeldieet-maakte-van-de-wolf-een-hond-context4.png$$,
   $$Axelsson analyseerde het DNA van 12 wolven en 60 honden. De wolven kwamen van verschillende continenten en de honden behoorden tot 14 rassen. Drie uitspraken over deze onderzoeksgroep zijn:
1 Een hond en een wolf die samen vruchtbare nakomelingen kunnen voortbrengen behoren tot dezelfde soort.
2 De 14 hondenrassen onderscheiden zich van elkaar doordat zij elk een kenmerkend fenotype hebben.
3 Bij de honden van één ras is het DNA volledig identiek.$$, 'inline'),
  ('54105cff-ef00-4289-848f-bcca7a16cca0', '8edfdb55-d98a-418e-877a-9455fca4008f', $$verschillen in genen voor vertering; drie resultaten voor het gen voor amylase$$,
   $$biologie-havo-2018-i-zetmeeldieet-maakte-van-de-wolf-een-hond-context5.png$$,
   $$Axelsson vond tussen de groep honden en de groep wolven verschillen in tien genen die een rol spelen bij de vertering van zetmeel en vetten. Nadat het onderzoek was opgeschaald tot 136 honden en 35 wolven vond de onderzoeker de volgende resultaten voor het gen voor amylase:
1 Alle wolven hadden twee kopieën van dit gen, terwijl de honden 4 tot 30 kopieën hadden.
2 Bij honden werd elk gen voor amylase gemiddeld 28 keer vaker afgelezen dan bij wolven.
3 Amylase van honden was efficiënter in het ‘knippen’ van zetmeel dan amylase van wolven.$$, 'inline'),
  ('2dcc580b-4089-46be-86c5-1e9f6e7d87cf', '8edfdb55-d98a-418e-877a-9455fca4008f', $$verschillen in vertering van zetmeel tot glucose en opname; insuline$$,
   $$biologie-havo-2018-i-zetmeeldieet-maakte-van-de-wolf-een-hond-context6.png$$,
   $$Uit het onderzoek van Axelsson bleek ook dat er verschillen waren tussen de verdere vertering van zetmeel tot glucose en de opname daarvan in de cellen van de dunne darm en in andere lichaamscellen. Insuline bevordert de opname van glucose uit het bloed door de lichaamscellen.$$, 'inline'),
  ('7c5148af-4b57-4b07-a64a-92b62b9d680e', '8edfdb55-d98a-418e-877a-9455fca4008f', $$vergelijkbare aanpassingen aan een zetmeelrijk dieet bij mensen$$,
   $$biologie-havo-2018-i-zetmeeldieet-maakte-van-de-wolf-een-hond-context7.png$$,
   $$Bij mensen heeft het zetmeelrijke dieet geleid tot vergelijkbare aanpassingen. Axelsson vindt zijn resultaten daarom een treffend voorbeeld van evolutie waarbij twee verschillende soorten, onafhankelijk van elkaar, dezelfde aanpassingen ontwikkelen.$$, 'inline'),
  ('b732f08e-2303-42b7-8625-4ecc206fc287', '2009b730-1c19-42c4-8de1-2479dda2602b', $$inleiding: na antibioticumbehandeling darminfectie met Clostridium difficile$$,
   $$biologie-havo-2018-i-poeptransplantatie-context1.png$$,
   $$De oma van Marah is met een ontsteking aan haar been in het ziekenhuis opgenomen. De ontsteking is daar behandeld met een antibioticum. Toen haar been begon te genezen kreeg oma last van diarree. Na enige tijd werd de diagnose gesteld: een darminfectie met Clostridium difficile.$$, 'inline'),
  ('01861286-f905-4822-8fc0-eaa58b6913eb', '2009b730-1c19-42c4-8de1-2479dda2602b', $$toxine van Clostridium difficile tast het epitheel van de dikke darm aan$$,
   $$biologie-havo-2018-i-poeptransplantatie-context2.png$$,
   $$Het toxine dat Clostridium difficile afgeeft, tast het epitheel (dekweefsel) van de dikke darm aan.$$, 'inline'),
  ('4fb95ed7-0dcd-4f46-9ab3-14a1ff23eb62', '2009b730-1c19-42c4-8de1-2479dda2602b', $$opnieuw antibiotica; Marah zoekt informatie op$$,
   $$biologie-havo-2018-i-poeptransplantatie-context3.png$$,
   $$De oma van Marah krijgt als behandeling opnieuw een antibioticumkuur voorgeschreven. Tijdens de biologieles heeft Marah gehoord dat antibioticagebruik ook nadelige kanten heeft. Ze zoekt op Wikipedia wat voor infectie haar oma eigenlijk heeft en leest het volgende:$$, 'inline'),
  ('f31c3be0-3429-4458-a6aa-27e20b6d9f24', '2009b730-1c19-42c4-8de1-2479dda2602b', $$informatie over Clostridium difficile en clostridiumziekte door antibioticagebruik$$,
   $$biologie-havo-2018-i-poeptransplantatie-context4.png$$,
   $$Clostridium difficile is een grampositieve, anaerobe, sporevormende staafbacterie die veel voorkomt in de darmen maar daar doorgaans geen problemen veroorzaakt. Bij 80% van de pasgeborenen en bij 9% van de volwassenen is deze bacterie aantoonbaar in de ontlasting (dus ook in hun darmstelsel). Overmatige groei van Clostridium difficile (clostridiumziekte) bij volwassenen kan ontstaan door het gebruik van antibiotica.$$, 'inline'),
  ('5383aa44-7bdc-440b-91bf-77d8d6d5c784', '2009b730-1c19-42c4-8de1-2479dda2602b', $$huisartsen zijn terughoudend met antibiotica$$,
   $$biologie-havo-2018-i-poeptransplantatie-context5.png$$,
   $$Nederlandse huisartsen zijn terughoudend in het voorschrijven van antibiotica. Zo proberen ze een risico te minimaliseren.$$, 'inline'),
  ('924e97a4-2de5-4e9c-99e9-dc5730a4e951', '2009b730-1c19-42c4-8de1-2479dda2602b', $$fecale bacterietherapie (poeptransplantatie) als alternatief voor antibiotica$$,
   $$biologie-havo-2018-i-poeptransplantatie-context6.png$$,
   $$De behandeling van clostridiumziekte met antibiotica duurt lang en vaak komen de klachten weer terug. Daarom werd in het AMC in Amsterdam een onderzoek gedaan naar het toepassen van fecale bacterietherapie, ofwel poeptransplantatie, als alternatief voor de antibioticumbehandeling. Internist Max Nieuwdorp legt uit hoe dit in zijn werk gaat: “Gezonde donoren leveren hun ontlasting in. Na menging met een vloeistof en filteren door een zeefje ontstaat een vloeistof die aan patiënten met een Clostridium-infectie kan worden toegediend. Op deze manier wordt de darm voorzien van een gezond bacteriebehang.”$$, 'inline'),
  ('04ee4269-6d5e-4faf-b349-b8e5d55115a8', '2009b730-1c19-42c4-8de1-2479dda2602b', $$toediening via een slangetje door de neus$$,
   $$biologie-havo-2018-i-poeptransplantatie-context7.png$$,
   $$De vloeistof wordt toegediend via een slangetje door de neus naar het spijsverteringskanaal.$$, 'inline'),
  ('c515cbe9-3b79-42c3-a319-2743c788df78', '2009b730-1c19-42c4-8de1-2479dda2602b', $$klinisch onderzoek: standaardbehandeling versus fecale bacterietherapie$$,
   $$biologie-havo-2018-i-poeptransplantatie-context8.png$$,
   $$Om de effectiviteit van fecale bacterietherapie te testen is uitgebreid klinisch onderzoek gedaan. Twee groepen patiënten met clostridiumziekte werden behandeld. Groep 1 kreeg een standaardbehandeling met antibiotica. Groep 2 kreeg fecale bacterietherapie. De poeptransplantatie bleek zo succesvol dat het experiment vroegtijdig werd gestopt om ook de patiënten van groep 1 daarmee te behandelen.$$, 'inline'),
  ('9759b518-c118-44bb-9ab7-4f2d1e375e24', '2009b730-1c19-42c4-8de1-2479dda2602b', $$kweek van darmbacteriën onder omstandigheden van de dikke darm$$,
   $$biologie-havo-2018-i-poeptransplantatie-context9.png$$,
   $$Marah vindt zo’n poeptransplantatie wel een vies idee. Ze vraagt zich af of de bacteriën niet eenvoudig in een laboratorium gekweekt kunnen worden, zodat de patiënten in plaats van poep een bacteriepreparaat toegediend kunnen krijgen. Max Nieuwdorp verwacht dat verder onderzoek inderdaad zal leiden tot een preparaat met specifieke soorten gekweekte darmbacteriën. Bij een kweek moeten de abiotische factoren overeenkomen met de omstandigheden in de dikke darm.$$, 'inline'),
  ('3dbf2140-cf64-420a-ad94-33f9b4ed17f4', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$inleiding: de vuursalamander dreigt uit te sterven; actieplan van RAVON$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context1.png$$,
   $$Onze meest spectaculaire salamander, de vuursalamander, verkeert in nood en dreigt de eerste amfibie te worden die deze eeuw in Nederland uitsterft. Om dit te voorkomen startte RAVON (reptielen-, amfibieën-, vissenonderzoek Nederland) met het actieplan ‘SOS vuursalamander’.$$, 'inline'),
  ('4551fe81-49ef-4812-87f0-eb40f85317ad', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$vuursalamander (afbeelding 1): leefgebied, voedsel en natuurlijke vijanden$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context2.png$$,
   $$afbeelding 1: foto van een vuursalamander
De vuursalamander (Salamandra salamandra, afbeelding 1) is in Nederland de enig voorkomende landsalamander. Vuursalamanders leven in de vochtige loofbossen met bronbeekjes van Zuid-Limburg.
Het voedsel van de volwassen vuursalamander bestaat vooral uit wormen en naaktslakken. Ook sommige geleedpotigen en hun larven staan op het menu, vooral de wat tragere dieren zoals miljoenpoten, pissebedden en rupsen. De larven van de vuursalamander leven hoofdzakelijk van kleine algen-etende watervlooien.
Er is niet veel bekend over natuurlijke vijanden van de volwassen vuursalamander. Oudere exemplaren zijn waarschijnlijk te giftig om door andere dieren gegeten te worden. Jongere exemplaren zijn nog niet zo giftig en vormen een prooi voor loopkevers. De larven van de vuursalamander worden gegeten door de beekforel, libellenlarven, waterkevers en de waterspitsmuis.$$, 'inline'),
  ('62d982a8-5dbd-47c6-a5bb-b30e867624fb', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$in de tekst wordt een voedselweb beschreven$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context3.png$$,
   $$In de bovenstaande tekst wordt een voedselweb beschreven.$$, 'inline'),
  ('0e9fa5f3-0692-4f71-a391-9d6376a703c6', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$jaarlijkse tellingen van larven en volwassen vuursalamanders$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context4.png$$,
   $$Medewerkers van RAVON bepalen jaarlijks de grootte van de vuursalamanderpopulatie door op verschillende plekken:
− larven te zoeken en te tellen in de poelen waarin vuursalamanders zich voortplanten;
− volwassen dieren te tellen langs een vastgesteld traject op het land. Met de gegevens van deze tellingen wordt de ontwikkeling bepaald van de populatie vuursalamanders in het wild (afbeelding 2).$$, 'inline'),
  ('19c0227d-e6ab-431e-bd53-8a140998cb14', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$afbeelding 2: populatiegrootte vuursalamanders 1997-2015 (index 1997 = 100)$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context5.png$$,
   $$afbeelding 2: lijngrafiek van de populatiegrootte vuursalamanders als index (1997 = 100), 1997-2015. De index piekt rond 1999 en 2007 en daalt na 2008 sterk; vanaf 2011 ligt de index rond 0.$$, 'inline'),
  ('da63aa96-90fc-411d-a956-6c39bddcc4dd', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$in 2010 werd alarm geslagen$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context6.png$$,
   $$In 2010 werd alarm geslagen: “De vuursalamander dreigt uit te sterven in Nederland.”$$, 'inline'),
  ('350a74da-20a9-48ae-a367-ca2949ec613a', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$doelen van het actieplan; gezonde vuursalamanders in gevangenschap$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context7.png$$,
   $$Met het actieplan SOS vuursalamander wilde RAVON:
− de oorzaak van de achteruitgang vaststellen;
− de laatste vuursalamanders veiligstellen;
− een kweekprogramma opzetten.
Een aantal gezonde vuursalamanders werd daarom door medewerkers van RAVON gevangen om de soort veilig te stellen. Deze vuursalamanders leven nu in gevangenschap.$$, 'inline'),
  ('e3e28aef-e939-44fe-8c39-aea9b8abbcd2', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$in 2015 was de vuursalamander in het wild nog niet uitgestorven$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context8.png$$,
   $$Hoewel de grafiek in afbeelding 2 anders doet vermoeden, was de vuursalamander in 2015 ook in het wild nog niet uitgestorven in Nederland.$$, 'inline'),
  ('117c7c3d-d621-4f10-be15-8caf8df154da', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$dode vuursalamanders; schimmel Batrachochytrium salamandrivorans geïdentificeerd$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context9.png$$,
   $$Vanaf 2008 werden steeds vaker dode vuursalamanders gevonden. Omdat veel van deze dode vuursalamanders zweren op hun huid hadden, werd al snel gedacht aan een ziekteverwekker. In 2013 identificeerden onderzoekers de tot dan toe onbekende schimmel Batrachochytrium salamandrivorans, die dodelijk bleek te zijn voor de vuursalamander. Met de identificatie van deze schimmel was de eerste doelstelling van SOS vuursalamander gehaald.$$, 'inline'),
  ('6d134b1c-c485-4b28-9e29-d067edfef3f0', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$inleiding tabel 1: kenmerken van vier ziekteverwekkers$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context10.png$$,
   $$In tabel 1 zijn kenmerken van vier ziekteverwekkers weergegeven.$$, 'inline'),
  ('8b8dd0d8-9b45-4c81-b9ae-2dc2c64e4cdd', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$tabel 1: celwand of eiwitmantel, kernmembraan en erfelijk materiaal van vier ziekteverwekkers$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context11.png$$,
   $$tabel 1 (ziekteverwekker – celwand of eiwitmantel – kernmembraan – erfelijk materiaal)
1 – celwand – aanwezig – DNA
2 – eiwitmantel – afwezig – RNA
3 – celwand – afwezig – DNA
4 – afwezig – aanwezig – DNA$$, 'inline'),
  ('d54b5858-a81b-4001-95b8-0f70b68dc1fc', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$detectietest op DNA van de schimmel met een wattenstaafje (afbeelding 3)$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context12.png$$,
   $$Onderzoekers ontwikkelden een detectietest om een DNA-volgorde op te sporen die uniek is voor de schimmel. Met een wattenstaafje worden enkele cellen van de huid van gevangen vuursalamanders verkregen (afbeelding 3). Met de detectiemethode kan snel worden bepaald of het monster besmet is. Als dat zo is, wordt de vuursalamander behandeld met een schimmeldodend middel.
afbeelding 3: foto van een vuursalamander die met een wattenstaafje wordt bemonsterd$$, 'inline'),
  ('a80dd2c3-03ef-4dc0-bd80-8a05ae8675a4', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$monster kan cellen van vuursalamander, algen en bacteriën bevatten; evolutionaire stamboom$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context13.png$$,
   $$Het te onderzoeken monster kan naast cellen van de ziekteverwekker ook cellen van de vuursalamander (1), van algen (2) en van bacteriën (3) bevatten. Afbeelding 4 geeft de evolutionaire stamboom van de organismen op aarde weer.$$, 'inline'),
  ('8754dafb-aa9e-4ca3-abb4-25b398cfe4bb', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$afbeelding 4: evolutionaire stamboom van de organismen op aarde$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context14.png$$,
   $$afbeelding 4: evolutionaire stamboom met takken naar bacteriën, wieren/algen, hogere planten, schimmels en dieren.$$, 'inline'),
  ('5db1cec4-bd9b-41c3-b7e8-4cea372324ba', '6e4a99cd-6ae1-49a6-a1a5-04fecdd33447', $$natuurbeheerder met een populatie van besmette en niet-besmette vuursalamanders$$,
   $$biologie-havo-2018-i-actieplan-sos-vuursalamander-context15.png$$,
   $$De detectietest kan worden gebruikt bij het beheer van de vuursalamanderpopulaties. Een natuurbeheerder treft in zijn gebied een populatie aan die bestaat uit zowel besmette als niet-besmette vuursalamanders.$$, 'inline');

