   '["genetische variatie", "kloon", "ongeslachtelijke voortplanting", "monocultuur", "vatbaarheid voor ziekten", "resistentie"]'::jsonb,
   $$Uitleggen waarom gebrek aan genetische variatie in een kloon een gewas kwetsbaar maakt voor ziekten.$$,
   $$biologie-havo-2018-i-bananen-bedreigd-vraag19.png$$, $$2p 19 Leg uit dat het gebruik van één bananenkloon een plantage extra kwetsbaar maakt voor schimmelziekten.$$, array['2d1ab85d-7e66-4c49-9738-98c974034f31', '87534368-fb3d-469c-9e3b-b970fcc56c9f', 'a620cd0b-b480-4bee-8aba-c0ca57c4b9fb']::uuid[]),
